import { Line } from '@visx/shape';
import React from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { LeftMagnifier } from './components/LeftMagnifier.js';
import { RightMagnifier } from './components/RightMagnifier.js';
import { _usePoliteContainer } from '../../../../overlays/hooks/_usePoliteContainer.js';
import { useOverlaysEvents } from '../../hooks/useOverlaysEvents.js';

interface HorizontalCrosshairProps {
  /** Coordinate y for crosshair */
  y: number;
  /** Left label for crosshair */
  leftLabel?: string;
  /** Right label for the crosshair */
  rightLabel?: string;
  /** Width for crosshair line */
  width: number;
  /** Top margin for crosshair line */
  top?: number;
  /** Left offset */
  leftOffset?: number;
  /** Right offset */
  rightOffset?: number;
  /** Indicates wether the line needs to be dashed */
  dashed?: boolean;
}

export const HorizontalCrosshair = (props: HorizontalCrosshairProps) => {
  const {
    y,
    leftLabel,
    rightLabel,
    width,
    top = 0,
    leftOffset = 0,
    rightOffset = 0,
    dashed = true,
  } = props;

  const lineStrokeDasharray = dashed ? '3,2' : '0,0';

  const Portal = _usePoliteContainer();

  const from = { x: -leftOffset, y: top + y };
  const to = { x: width - leftOffset, y: top + y };
  const strokeWidth = 1;
  const { isInChartBounds } = useOverlaysEvents();

  return isInChartBounds ? (
    <>
      {y > 0 && (
        <Line
          data-testid="crosshair"
          from={from}
          to={to}
          stroke={Colors.Border.Neutral.Accent}
          strokeWidth={strokeWidth}
          strokeDasharray={lineStrokeDasharray}
          pointerEvents={'none'}
        />
      )}
      {leftLabel && (
        <Portal>
          <LeftMagnifier label={leftLabel} mouseY={y} offset={leftOffset} />
        </Portal>
      )}
      {rightLabel && (
        <Portal>
          <RightMagnifier label={rightLabel} mouseY={y} offset={rightOffset} />
        </Portal>
      )}
    </>
  ) : null;
};

HorizontalCrosshair['displayName'] = 'HorizontalCrosshair';
